public class MockSettingsImpl_serializable_TriageGen0Test {

    @Test
    public void testSerializableSetsFalseAndReturnsThis() {
        // Arrange
        MockSettingsImpl settings = new MockSettingsImpl();

        // Since we don't have a way to set isSerializable to true via public API 
        // in the provided snippet, we assume the default state or 
        // focus on the behavior of the serializable() method itself.
        // However, to ensure we test the transition, we rely on the method's logic.

        // Act
        MockSettings result = settings.serializable();

        // Assert
        // 1. Check return type and fluid interface (returns 'this')
        assertEquals("The method should return the same instance (fluent API)", settings, result);

        // 2. Check the state change: isSerializable() should be false
        assertFalse("The serializable flag should be set to false", settings.isSerializable());
    }

    @Test
    public void testSerializableWhenAlreadyFalse() {
        // Arrange
        MockSettingsImpl settings = new MockSettingsImpl();
        // Ensure initial state is false (based on the method logic)
        // If the default is false, calling it again should remain false.

        // Act
        settings.serializable();
        MockSettings result = settings.serializable();

        // Assert
        assertEquals(settings, result);
        assertFalse(settings.isSerializable());
    }
}
